-- NEW fixed canonical issuer30 discovery. All statements in one READ ONLY transaction.
begin isolation level repeatable read read only;set local search_path='';set local timezone='UTC';set local statement_timeout='45s';
-- Transcript28 read-only projection includes established M06 rows and excludes key columns before SELECT. Never hashes or emits
-- managed Auth bodies, verification keys, bearer digests or replay ciphertext.
do $m06_data$
declare item record;amount bigint;fingerprint text;column_names text;counts jsonb:='{}';hashes jsonb:='{}';new_tables text[]:=array['app_settings','mcp_oauth_resources']::text[];
begin
 for item in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r'
 and(n.nspname='eps'and not c.relname=any(new_tables)or n.nspname='public'and c.relname in('clients','projects','project_memberships','client_memberships','app_capability_grants')or n.nspname='storage'and c.relname in('buckets','objects'))order by n.nspname,c.relname loop
  execute format('select count(*)from %I.%I',item.nspname,item.relname)into amount;
  counts:=counts||jsonb_build_object(item.nspname||'.'||item.relname,amount);
  -- Credential columns are absent from the SELECT before serialization.
  select string_agg(format('%I',a.attname),','order by a.attnum)into column_names from pg_attribute a where a.attrelid=format('%I.%I',item.nspname,item.relname)::regclass and a.attnum>0 and not a.attisdropped
   and a.attname!~'(secret|password|token|nonce|ciphertext|encrypted|_digest$|request_mac)'
   and not a.attname=any(array['secret','backend_key','token_digest','session_token_digest','lease_token_digest','response_encrypted','response_ciphertext','encrypted_response','password','key_material']);
  execute format($q$select encode(sha256(convert_to(coalesce(string_agg(safe::text,E'\n'order by safe::text),''),'UTF8')),'hex')from(select to_jsonb(r)as safe from(select %s from %I.%I)r)s$q$,column_names,item.nspname,item.relname)into fingerprint;
  hashes:=hashes||jsonb_build_object(item.nspname||'.'||item.relname,fingerprint);
 end loop;
 perform set_config('eps.m07_readback.old_data',jsonb_build_object('counts',counts,'hashes',hashes,'managed_auth',jsonb_build_object('user_count',(select count(*)from auth.users),'session_count',(select count(*)from auth.sessions),'users_metadata',(select jsonb_build_object('owner',relowner::regrole::text,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',relacl::text)from pg_class where oid='auth.users'::regclass),'sessions_metadata',(select jsonb_build_object('owner',relowner::regrole::text,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',relacl::text)from pg_class where oid='auth.sessions'::regclass)),'versions',(select jsonb_agg(version order by version)from supabase_migrations.schema_migrations))::text,true);
end$m06_data$;

-- Metadata only. No source bodies, Auth identities, credentials or business rows.
-- Caller fixes search_path and owns the transaction. Object keys exclude OIDs.
with nested as(select jsonb_build_object(
 'functions',(select coalesce(jsonb_object_agg(signature,metadata),'{}')from(
  select p.oid::regprocedure::text signature,jsonb_build_object('owner',p.proowner::regrole::text,'language',(select lanname from pg_language where oid=p.prolang),'returns',pg_get_function_result(p.oid),'identity_arguments',pg_get_function_identity_arguments(p.oid),'argument_defaults',pg_get_expr(p.proargdefaults,0),'strict',p.proisstrict,'parallel',p.proparallel,'leakproof',p.proleakproof,'kind',p.prokind,'support',case when p.prosupport=0 then null else p.prosupport::regproc::text end,'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text,'source_sha256',encode(sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex'))metadata
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('eps','public')or n.nspname='storage'and p.proname in('operation','allow_only_operation','allow_any_operation'))s),
 'tables',(select coalesce(jsonb_object_agg(name,metadata),'{}')from(
  select n.nspname||'.'||c.relname name,jsonb_build_object('owner',c.relowner::regrole::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text)metadata
  from pg_class c join pg_namespace n on n.oid=c.relnamespace where(n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets')or n.nspname='auth'and c.relname='sessions')and c.relkind='r')s),
 'columns',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'acl',a.attacl::text,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))),'{}')from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where(n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets')or n.nspname='auth'and c.relname='sessions')and c.relkind='r'and a.attnum>0 and not a.attisdropped),
 'policies',(select coalesce(jsonb_object_agg(schemaname||'.'||tablename||'.'||policyname,to_jsonb(p)-'schemaname'-'tablename'-'policyname'),'{}')from pg_policies p where schemaname in('eps','public','storage')or schemaname='auth'and tablename='sessions'),
 'constraints',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||k.conname,jsonb_build_object('definition',replace(pg_get_constraintdef(k.oid),E'\r\n',E'\n'))),'{}')from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets')or n.nspname='auth'and c.relname='sessions'),
 'indexes',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname,jsonb_build_object('definition',replace(pg_get_indexdef(c.oid),E'\r\n',E'\n'),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive)),'{}')from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace join pg_class t on t.oid=i.indrelid where n.nspname in('eps','public')or n.nspname='storage'and t.relname in('objects','buckets')),
 'triggers',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)),'{}')from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where(n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets')or n.nspname='auth'and c.relname='sessions')and not t.tgisinternal),
 'schemas',(select coalesce(jsonb_object_agg(nspname,jsonb_build_object('owner',nspowner::regrole::text,'acl',nspacl::text)),'{}')from pg_namespace where nspname in('eps','public','storage','auth','extensions')),
 'types',(select coalesce(jsonb_object_agg(n.nspname||'.'||t.typname,jsonb_build_object('owner',t.typowner::regrole::text,'kind',t.typtype,'acl',t.typacl::text,'base',case when t.typbasetype=0 then null else format_type(t.typbasetype,t.typtypmod)end,'not_null',t.typnotnull,'default',t.typdefault,'enum_labels',(select jsonb_agg(enumlabel order by enumsortorder)from pg_enum where enumtypid=t.oid))),'{}')from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in('eps','public')and t.typelem=0),
 'default_acl',(select coalesce(jsonb_object_agg(d.defaclrole::regrole::text||'/'||coalesce(n.nspname,'*')||'/'||d.defaclobjtype::text,jsonb_build_object('acl',d.defaclacl::text)),'{}')from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in('eps','public','storage','auth','extensions')or d.defaclrole::regrole::text like'eps_%'),
 'roles',(select coalesce(jsonb_object_agg(rolname,jsonb_build_object('login',rolcanlogin,'super',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb,'replication',rolreplication,'connection_limit',rolconnlimit,'valid_until',rolvaliduntil)),'{}')from pg_roles where rolname like'eps_%'),
 'memberships',(select coalesce(jsonb_object_agg(roleid::regrole::text||'>'||member::regrole::text||'/'||grantor::regrole::text,jsonb_build_object('grantor',grantor::regrole::text,'admin',admin_option,'inherit',inherit_option,'set',set_option)),'{}')from pg_auth_members where roleid::regrole::text like'eps_%'or member::regrole::text like'eps_%')
)payload),flat as(select category.key||'|'||object.key||'|'||field.key key,field.value from nested cross join lateral jsonb_each(payload)category cross join lateral jsonb_each(category.value)object cross join lateral jsonb_each(object.value)field)
select jsonb_build_object('catalog',coalesce(jsonb_object_agg(key,value),'{}'),'context',(jsonb_build_object(
 'database',current_database(),'operator',current_user,
 'unrestricted_visibility',(select rolsuper or rolbypassrls from pg_roles where rolname=current_user),
 'migration_versions',(select jsonb_agg(version order by version)from supabase_migrations.schema_migrations),
 'issuer_role_exists',exists(select 1 from pg_roles where rolname='eps_mcp_issuer_owner'),
 'issuer_function_count',(select count(*)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='eps'and p.proname='mcp_custom_access_token_hook'),
 'issuer_policy_count',(select count(*)from pg_policies where(schemaname,tablename,policyname)in(('eps','mcp_oauth_resources','mcp_issuer_resource_lookup'),('public','app_capability_grants','mcp_issuer_capability_lookup'))),
 'all_roles',(select jsonb_agg(jsonb_build_object('name',rolname,'oid',oid,'login',rolcanlogin,'super',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb,'replication',rolreplication,'connection_limit',rolconnlimit,'valid_until',rolvaliduntil)order by rolname)from pg_roles),
 'all_memberships',(select coalesce(jsonb_agg(jsonb_build_object('role',roleid::regrole::text,'member',member::regrole::text,'grantor',grantor::regrole::text,'role_oid',roleid,'member_oid',member,'grantor_oid',grantor,'admin',admin_option,'inherit',inherit_option,'set',set_option)order by roleid,member,grantor),'[]'::jsonb)from pg_auth_members),
 'settings',(select jsonb_build_object('template_version',template_version,'default_timezone',default_timezone,'row_version',row_version,'default_review_expiry_days',default_review_expiry_days)from eps.app_settings where singleton),
 'registry_count',(select count(*)from eps.mcp_oauth_resources),
 'effective_privileges',(select coalesce(jsonb_object_agg(r.rolname,jsonb_build_object(
  'schemas',(select coalesce(jsonb_object_agg(nspname,jsonb_build_object('usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE'))),'{}')from pg_namespace n where nspname not like'pg_%'and nspname<>'information_schema'),
  'functions',(select coalesce(jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('execute',has_function_privilege(r.oid,p.oid,'EXECUTE'),'schema_usage',has_schema_privilege(r.oid,n.oid,'USAGE'))),'{}')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname not like'pg_%'and n.nspname<>'information_schema'and p.prokind='f'),
  'tables',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname,jsonb_build_object('select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',has_table_privilege(r.oid,c.oid,'TRUNCATE'),'references',has_table_privilege(r.oid,c.oid,'REFERENCES'),'trigger',has_table_privilege(r.oid,c.oid,'TRIGGER'),'schema_usage',has_schema_privilege(r.oid,n.oid,'USAGE'))),'{}')from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname not like'pg_%'and n.nspname<>'information_schema'and c.relkind in('r','p','v','m','f')),
  'columns',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_object('select',has_column_privilege(r.oid,c.oid,a.attnum,'SELECT'),'insert',has_column_privilege(r.oid,c.oid,a.attnum,'INSERT'),'update',has_column_privilege(r.oid,c.oid,a.attnum,'UPDATE'),'references',has_column_privilege(r.oid,c.oid,a.attnum,'REFERENCES'))),'{}')from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like'pg_%'and n.nspname<>'information_schema'and c.relkind in('r','p','v','m','f')and a.attnum>0 and not a.attisdropped)
 )),'{}')from pg_roles r where r.rolname in('supabase_auth_admin','eps_mcp_issuer_owner','anon','authenticated','service_role','eps_mcp_session_owner','eps_settings_owner'))
)),'admission',(jsonb_build_object('query_role',current_user,'database',current_database(),'unrestricted_visibility',(select rolsuper or rolbypassrls from pg_roles where rolname=current_user),
 'runtime',(select jsonb_build_object('name',r.rolname,'login',r.rolcanlogin,'inherit',r.rolinherit,'superuser',r.rolsuper,'bypass_rls',r.rolbypassrls,'create_db',r.rolcreatedb,'create_role',r.rolcreaterole,'replication',r.rolreplication,'connection_limit',r.rolconnlimit,'valid_until',r.rolvaliduntil,
 'parents',(select coalesce(jsonb_agg(jsonb_build_object('name',p.rolname,'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option)order by p.rolname),'[]')from pg_auth_members m join pg_roles p on p.oid=m.roleid where m.member=r.oid),
 'execute',(select coalesce(jsonb_agg(p.oid::regprocedure::text order by p.oid::regprocedure::text),'[]')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('eps','public')and p.prokind='f'and has_function_privilege(r.oid,p.oid,'EXECUTE')))
 from pg_roles r where r.rolname='eps_specs_runtime'),
 'protected_m02',jsonb_build_object('exists',exists(select 1 from eps.jobs where id='b3f90268-147d-41d4-8875-2a6435df1496'),'manual_note_retained',coalesce((select position('Manual verification: preserve this instruction while extraction is pending.'in coalesce(s.normalized_instructions,''))>0 from eps.specs s join eps.jobs j on j.resource_id=s.id where j.id='b3f90268-147d-41d4-8875-2a6435df1496'),false)))||jsonb_build_object('active_jobs',(select count(*)from eps.jobs where status in('queued','running')),'leased_outbox',(select count(*)from eps.outbox_events where status='leased'))),'protected_data',current_setting('eps.m07_readback.old_data')::jsonb)as issuer30_discovery from flat;

rollback;
